const MG_INSTRUCTOR_LINE='You hold the flame steady, and those who approach decide whether to trust you.';
const MG={active:false,shown_tip:false,t:0,flame:0.5,target:0.5,target_drift_t:0,nomads:[],entry_t:0,exit_t:0,won:false,failed:false,fail_reason:''};
function mgInit(st){const s=st||MG;s.active=false;s.shown_tip=false;s.t=0;s.flame=0.5;s.target=0.5;s.target_drift_t=0;s.nomads=[];for(let i=0;i<8;i++){const a=i*Math.PI/4;s.nomads.push({a:a,d:180,commit:0.5,alive:true});}s.entry_t=0;s.exit_t=0;s.won=false;s.failed=false;s.fail_reason='';return s;}
function mgStep(s,clicked,dt){if(s.exit_t>0){s.exit_t+=dt;return s;}s.t+=dt;if(s.entry_t<48){s.entry_t+=dt;return s;}if(clicked)s.flame=Math.min(1,s.flame+0.18);s.flame=Math.max(0,s.flame-0.006*dt);s.target_drift_t+=dt;if(s.target_drift_t>120){s.target_drift_t=0;s.target=0.45+Math.random()*0.15;}const inBand=s.flame>=s.target-0.08&&s.flame<=s.target+0.12;let allClose=true,anyAlive=false;for(const n of s.nomads){if(!n.alive)continue;anyAlive=true;if(s.flame>s.target+0.25){n.commit=Math.max(0,n.commit-0.015*dt);if(n.commit<0.2){n.alive=false;s.failed=true;s.fail_reason='bright';}}else if(s.flame<s.target-0.15){n.commit=Math.max(0,n.commit-0.01*dt);if(n.commit<0.25){n.alive=false;s.failed=true;s.fail_reason='dim';}}else if(inBand){n.commit=Math.min(1,n.commit+0.008*dt);n.d=Math.max(32,n.d-0.25*dt);}else{n.d=Math.max(32,n.d-0.08*dt);}if(n.d>32)allClose=false;}if(!anyAlive&&!s.won){s.failed=true;if(!s.fail_reason)s.fail_reason='dim';}if(allClose&&anyAlive&&!s.failed){s.won=true;s.exit_t=1;}if(s.failed&&s.exit_t===0)s.exit_t=1;return s;}
if(location.hash.includes('mg')){const _origNG=newGame;newGame=function(pole){_origNG(pole);MG.active=true;mgInit(MG);MG.shown_tip=false;};}
